int handle_client_message(gpointer data) {
    Client *client = (Client *)data;

    if (!client->tls_handshake_complete) {
        if (perform_tls_handshake(client) != 0) {
            return -1;
        }
        client->tls_handshake_complete = true;
        notify_other_clients_of_connection(client);
    }

    if (!client->connected) {
        return -1;
    }

    while (true) {
        ssize_t bytes_read = read_tls_message(client, client->buffer, sizeof(client->buffer));
        if (bytes_read <= 0) {
            handle_client_disconnect(client);
            return -1;
        }

        Message *msg = parse_message(client->buffer, bytes_read);
        if (msg == NULL) {
            return -1;
        }

        update_client_details(client, msg);
        process_message(msg, client);

        if (!client->has_more_messages) {
            break;
        }
    }

    return 0;
}

int handle_client_message(gpointer data) {
