int handle_client_message(gpointer data) {
    Client *client = (Client *)data;

    if (!tls_handshake_complete(client->tls_session)) {
        if (perform_tls_handshake(client->tls_session) != 0) {
            return -1;
        }
        notify_clients_of_handshake_success(client);
    }

    while (1) {
        ssize_t bytes_read = read_message_from_tls(client->tls_session, client->buffer, sizeof(client->buffer));
        if (bytes_read <= 0) {
            if (bytes_read == 0 || (errno == SSL_ERROR_EOF)) {
                handle_client_disconnect(client);
                return -1;
            }
            break; // Non-fatal error or no data, break and return
        }

        Message *msg = parse_message_buffer(client->buffer, bytes_read);
        if (!msg) {
            continue; // Skip invalid or malformed messages
        }

        update_client_details_from_message(client, msg);
        if (invoke_message_processor(msg, client) != 0) {
            handle_client_disconnect(client);
            return -1;
        }

        free_message(msg);
    }

    return 0;
}

